//! Atari 8-bit support: ATASCII character set, file format, keyboard and
//! key click.

pub mod atascii;
pub mod basic;
pub mod case;
pub mod click;
pub mod keyboard;
pub mod mac65;
pub mod msbasic;
pub mod palette;
pub mod pctext;
pub mod tokenize;

use retro_core::{CaseOffer, Decoded, FileFormat, Machine, TabStops};

/// Standard ATASCII glyphs $00-$FF (normal $00-$7F, inverse $80-$FF),
/// 8 bytes each. Generated by `tools/fontgen` from "EightBit Atari"
/// (c) 2018 Steve Boswell, SIL Open Font License 1.1 -- see
/// `assets/fonts/atari/OFL.txt`.
static FONT: &[u8; 2048] = include_bytes!("font_atascii.bin");

/// The XL/XE international character set (CHBAS = $CC), from the same font's
/// U+E100 block. Generated with `fontgen --lenient`: 16 accented letters
/// have outline points between pixel centres, which don't change any pixels;
/// they were checked by eye (see docs/images/font_international_sheet.png).
static FONT_INTL: &[u8; 2048] = include_bytes!("font_international.bin");

/// Index of the international set in [`Machine::charsets`].
pub const INTERNATIONAL: usize = 1;

/// The font licence text, for display in the About screen.
pub const FONT_LICENSE: &str = include_str!("../../../assets/fonts/atari/OFL.txt");

/// File formats. The BASIC dialects share a file layout; `format::detect`
/// picks by extension (.TUR, .BXL, .BXE) or best fit, earlier winning a
/// tie, so a program using only Atari BASIC's keywords reads as Atari
/// BASIC. Plain ATASCII text last.
static FORMATS: &[&dyn FileFormat] = &[
    &basic::ATARI_BASIC_FILE,
    &basic::TURBO_BASIC_XL_FILE,
    &basic::ALTIRRA_EXTENDED_BASIC_FILE,
    &basic::ALTIRRA_BASIC_FILE,
    &basic::BASIC_XL_FILE,
    &basic::BASIC_XE_FILE,
    &basic::BASIC_A_PLUS_FILE,
    &mac65::Mac65,
    &msbasic::MicrosoftBasic,
    &atascii::AtasciiText,
];

#[derive(Debug, Default, Clone, Copy)]
pub struct Atari {
    /// 0 = standard ATASCII, 1 = international.
    charset: usize,
}

impl Machine for Atari {
    fn name(&self) -> &'static str {
        "Atari 8-bit"
    }

    fn glyph(&self, code: u8) -> [u8; 8] {
        let font = if self.charset == INTERNATIONAL {
            FONT_INTL
        } else {
            FONT
        };
        let i = code as usize * 8;
        font[i..i + 8].try_into().unwrap()
    }

    fn charsets(&self) -> &'static [&'static str] {
        &["Graphics", "International"]
    }

    fn charset(&self) -> usize {
        self.charset
    }

    fn set_charset(&mut self, index: usize) {
        self.charset = index.min(INTERNATIONAL);
    }

    fn space(&self) -> u8 {
        b' '
    }

    fn screen_columns(&self) -> usize {
        40
    }

    fn left_margin(&self) -> usize {
        2
    }

    /// The OS power-up TABMAP: physical columns 7, 15, 23, ... 119 of a
    /// three-row, 40-column logical line.
    fn default_tab_stops(&self) -> TabStops {
        TabStops::every(8, 7, 40, 2, 3)
    }

    /// ATASCII characters that match ASCII stay ASCII on the clipboard;
    /// graphics, arrows, inverse etc. use U+E000 + code, the private-use
    /// range where the EightBit Atari font puts the same glyphs. With the
    /// international set, accented letters are real Unicode letters and
    /// their inverse forms use the font's U+E100 range.
    fn char_for_code(&self, code: u8) -> char {
        pctext::char_for_code(code, self.charset == INTERNATIONAL)
    }

    fn code_for_char(&self, c: char) -> Option<u8> {
        pctext::code_for_char(c, self.charset == INTERNATIONAL)
    }

    fn import_text(&self, bytes: &[u8]) -> Decoded {
        atascii::import(bytes)
    }

    fn case_offer(&self, lines: &[Vec<u8>]) -> Option<CaseOffer> {
        let kind = case::listing_kind(lines)?;
        let (lines, changed) = case::uppercase(lines, kind)?;
        let (what, kept) = match kind {
            case::Listing::Basic => ("a BASIC program", "Strings, REM and DATA"),
            case::Listing::Assembler => ("an assembler program", "Strings and ; comments"),
        };
        Some(CaseOffer {
            what,
            kept,
            lines,
            changed,
        })
    }

    fn looks_like_pc_text(&self, bytes: &[u8]) -> bool {
        atascii::looks_like_pc_text(bytes)
    }

    fn export_standard(&self, line: &[u8]) -> (String, usize) {
        pctext::to_standard(line, self.charset == INTERNATIONAL)
    }

    /// Plain ASCII with `{tags}` (see `pctext`).
    fn export_ascii(&self, line: &[u8]) -> String {
        pctext::to_ascii(line)
    }

    fn formats(&self) -> &'static [&'static dyn FileFormat] {
        FORMATS
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use retro_core::Document;

    #[test]
    fn tab_follows_atari_stops() {
        use retro_core::{EditAction::*, Editor, Pos, WrapMode};
        let m = Atari::default();
        let doc = Document::from_lines(vec![b"AB".to_vec(), b"NEXT".to_vec()], true);
        let mut ed = Editor::new(doc, WrapMode::Native, m.default_tab_stops());
        let layout = ed.layout(&m, 40, 24);
        let tab = |ed: &mut Editor, a| {
            ed.apply(a, &layout, &m, false);
            ed.doc.cursor()
        };
        // Screen column 7 = text column 5; the line is padded with spaces.
        assert_eq!(tab(&mut ed, NextTabStop), Pos { line: 0, col: 5 });
        assert_eq!(ed.doc.line(0), b"AB   ");
        assert_eq!(tab(&mut ed, NextTabStop).col, 13);
        // Set a stop at column 15, clear the one at 21.
        ed.doc.move_to_col_padded(15, b' ');
        tab(&mut ed, SetTabStop);
        ed.doc.move_to_col_padded(21, b' ');
        tab(&mut ed, ClearTabStop);
        ed.doc.set_cursor(Pos { line: 0, col: 13 });
        assert_eq!(tab(&mut ed, NextTabStop).col, 15);
        assert_eq!(tab(&mut ed, NextTabStop).col, 29);
        // Column 37 is screen column 39; the next stop is on the second row.
        assert_eq!(tab(&mut ed, NextTabStop).col, 37);
        assert_eq!(tab(&mut ed, NextTabStop).col, 43);
        // Past the last stop of the logical line: start of the next line.
        ed.doc.set_cursor(Pos { line: 0, col: 43 });
        ed.doc.move_to_col_padded(113, b' ');
        assert_eq!(tab(&mut ed, NextTabStop), Pos { line: 1, col: 0 });
    }

    #[test]
    fn clipboard_round_trips_every_code() {
        use retro_core::clipboard::{from_text, to_text};
        let m = Atari::default();
        let all: Vec<u8> = (0..=255).filter(|&c| c != atascii::EOL).collect();
        let text = to_text(std::slice::from_ref(&all), &m);
        assert!(text.starts_with('\u{E000}'));
        assert!(text.contains("ABC"));
        let (lines, skipped) = from_text(&text, &m);
        assert_eq!((lines, skipped), (vec![all], 0));
        // Text from other programs: unknown characters are skipped.
        let (lines, skipped) = from_text("A{b}\r\nC\t\u{2665}", &m);
        assert_eq!(lines, vec![b"Ab".to_vec(), b"C ".to_vec()]);
        assert_eq!(skipped, 3);
    }

    #[test]
    fn replace_all_is_one_undo_step() {
        use retro_core::{Editor, WrapMode, search};
        let m = Atari::default();
        let doc = Document::from_lines(vec![b"A=A+1:A=2".to_vec(), b"PRINT A".to_vec()], true);
        let mut ed = Editor::new(doc, WrapMode::Native, m.default_tab_stops());
        let layout = ed.layout(&m, 40, 24);
        let at = search::find_all(
            ed.doc.lines(),
            b"A",
            search::Match {
                case: true,
                inverse: true,
            },
        );
        ed.replace_matches(&at, 1, b"COUNT", &layout);
        assert_eq!(ed.doc.lines()[0], b"COUNT=COUNT+1:COUNT=2");
        assert_eq!(ed.doc.lines()[1], b"PRINT COUNT");
        assert_eq!(ed.doc.cursor(), retro_core::Pos { line: 1, col: 11 });
        assert!(ed.undo(&layout));
        assert_eq!(ed.doc.lines()[0], b"A=A+1:A=2");
        assert_eq!(ed.doc.lines()[1], b"PRINT A");
    }

    #[test]
    fn undo_selection_and_paste() {
        use retro_core::{EditAction::*, Editor, Pos, WrapMode};
        let m = Atari::default();
        let doc = Document::from_lines(vec![b"HELLO".to_vec()], true);
        let mut ed = Editor::new(doc, WrapMode::Native, m.default_tab_stops());
        let layout = ed.layout(&m, 40, 24);
        ed.doc.set_cursor(Pos { line: 0, col: 5 });
        // Typing is one undo step.
        for &c in b" WORLD" {
            ed.apply(Insert(c), &layout, &m, false);
        }
        assert_eq!(ed.doc.line(0), b"HELLO WORLD");
        assert!(ed.undo(&layout));
        assert_eq!(ed.doc.line(0), b"HELLO");
        assert!(!ed.doc.is_modified());
        assert!(ed.redo(&layout));
        assert_eq!(ed.doc.line(0), b"HELLO WORLD");
        // Shift+Left x5 selects WORLD; typing replaces it.
        for _ in 0..5 {
            ed.apply(MoveLeft, &layout, &m, true);
        }
        assert_eq!(ed.copy(), Some(vec![b"WORLD".to_vec()]));
        ed.apply(Insert(b'X'), &layout, &m, false);
        assert_eq!(ed.doc.line(0), b"HELLO X");
        // Cut and paste across lines.
        ed.select_all();
        let cut = ed.cut(&layout).unwrap();
        assert_eq!(ed.doc.line(0), b"");
        ed.paste(&cut, &layout);
        ed.paste(&[b"1".to_vec(), b"2".to_vec()], &layout);
        assert_eq!(ed.doc.lines(), [b"HELLO X1".to_vec(), b"2".to_vec()]);
        assert!(ed.undo(&layout));
        assert!(ed.undo(&layout));
        assert_eq!(ed.doc.line(0), b"");
        assert!(ed.undo(&layout));
        assert_eq!(ed.doc.line(0), b"HELLO X");
    }

    #[test]
    fn international_set() {
        use retro_core::clipboard::{from_text, to_text};
        let mut m = Atari::default();
        let heart = m.glyph(0x00);
        m.set_charset(INTERNATIONAL);
        assert_ne!(m.glyph(0x00), heart);
        assert_eq!(m.glyph(b'A'), Atari::default().glyph(b'A'));
        // Accented letters go to the clipboard as real letters.
        let line = vec![0x14, b'T', 0x14, 0x94, 0x7B];
        let text = to_text(std::slice::from_ref(&line), &m);
        assert_eq!(text, "éTé\u{E194}Ä");
        assert_eq!(from_text(&text, &m), (vec![line], 0));
        // Every code still round-trips.
        let all: Vec<u8> = (0..=255).filter(|&c| c != atascii::EOL).collect();
        let text = to_text(std::slice::from_ref(&all), &m);
        assert_eq!(from_text(&text, &m), (vec![all], 0));
    }

    #[test]
    fn typing_after_a_click_does_not_select() {
        use retro_core::{EditAction::*, Editor, Pos, WrapMode};
        let m = Atari::default();
        let doc = Document::from_lines(vec![b"AB".to_vec()], true);
        let mut ed = Editor::new(doc, WrapMode::Native, m.default_tab_stops());
        let layout = ed.layout(&m, 40, 24);
        // A mouse click: cursor placed, drag started, released without moving.
        ed.click(Pos { line: 0, col: 1 }, false);
        ed.begin_drag();
        ed.apply(Insert(b'X'), &layout, &m, false);
        assert!(!ed.has_selection());
        ed.apply(Insert(b'Y'), &layout, &m, false);
        assert_eq!(ed.doc.line(0), b"AXYB");
    }

    #[test]
    fn font_has_expected_shapes() {
        let a = Atari::default();
        assert_eq!(a.glyph(b' '), [0; 8]);
        // Inverse space is a solid block.
        assert_eq!(a.glyph(0xA0), [0xFF; 8]);
        // Every inverse glyph is the bitwise NOT of its normal glyph.
        for c in 0..0x80u8 {
            let n = a.glyph(c);
            let i = a.glyph(c | 0x80);
            for r in 0..8 {
                assert_eq!(n[r], !i[r], "glyph ${c:02X} row {r}");
            }
        }
    }
}
